FROM dbo.Customers;

-- dbo.Customers: SELECT by key
SELECT Id, Name, Email, CountryId
FROM dbo.Customers
WHERE Id = @Id;

-- dbo.Customers: INSERT
INSERT INTO dbo.Customers (Name, Email, CountryId)
VALUES (@Name, @Email, @CountryId);

-- dbo.Customers: UPDATE
UPDATE dbo.Customers
SET
    Name = @Name,
    Email = @Email,
    CountryId = @CountryId
WHERE Id = @Id;

-- dbo.Customers: DELETE
DELETE FROM dbo.Customers
WHERE Id = @Id;

-- dbo.Customers: MERGE
MERGE INTO dbo.Customers AS t
USING (SELECT @Id AS Id, @Name AS Name, @Email AS Email, @CountryId AS CountryId) AS s
    ON t.Id = s.Id
WHEN MATCHED THEN
    UPDATE SET t.Name = s.Name, t.Email = s.Email, t.CountryId = s.CountryId
WHEN NOT MATCHED THEN
    INSERT (Name, Email, CountryId) VALUES (s.Name, s.Email, s.CountryId);

